// 12 精子と卵子 — 名前を付けた言葉：「卵子の最終面接」
import { C, clamp, ease, easeOut, pop, txt, note, head, person, card, arrow, loadMaps, maps, run, kami, worldMap, worldCentroid, icon } from '/pipeline3d/kami.js';
await loadMaps();
try { document.body.classList.add('band'); } catch (e) {}
const Y = C.gold, RED = '#e0453a', BLUE = '#8fc8ff', PINK = '#ff8fb0', EGG = '#bfe6ff', CX = 960;
const CH = ['プロローグ', '第1章', '第2章', '第3章', '第4章', '第5章', 'エピローグ'];
const K = (fn, chap, o = {}) => kami(fn, { chap, chaps: CH, ...o });
const R = (els, t) => { const rf = els.filter(e => e.ref), ot = els.filter(e => !e.ref); return run([...rf, ...ot].map(e => e.f ? e : { ...e, f: () => '' }), t); };
const ref = (s) => ({ at: .6, ref: true, f: () => note(1880, 58, s, 'end') });
const S_FZ = 'Fitzpatrick et al. (2020) Proc. R. Soc. B', S_MT = 'Martin (2018) / Fitzpatrickの説明', S_EGG = '浅田義正・河合蘭（2023）ほか', S_ART = '日本産科婦人科学会 ARTデータ（ニッセイ基礎研 2024）', S_LV = 'Levine et al. (2023) Human Reproduction Update', S_IVF = '日本産科婦人科学会（nippon.com 2026）';
const rng = (s) => () => { s = (s * 16807) % 2147483647; return s / 2147483647; };
const roll = (x, y, a, b, t, t0, dur, o = {}) => { const k = ease(clamp((t - t0) / dur)), v = a + (b - a) * k; const s0 = o.dec ? v.toFixed(o.dec) : (o.f ? o.f(v) : Math.round(v).toLocaleString('ja-JP')); return `<g style="font-variant-numeric:tabular-nums">${txt(x, y, (o.pre || '') + s0 + (o.unit || ''), { size: o.size || 96, color: o.color || Y, serif: true, anchor: o.anchor })}</g>`; };
const oku = (v) => v >= 1e8 ? (Math.floor(v / 1e8) + '億' + (Math.round((v % 1e8) / 1e4) ? Math.round((v % 1e8) / 1e4).toLocaleString('ja-JP') + '万' : '')) : v >= 1e4 ? Math.round(v / 1e4).toLocaleString('ja-JP') + '万' : Math.round(v).toLocaleString('ja-JP');
const stampR = (x, y, s0, t, t0, col = RED, size = 52) => { const st = clamp((t - t0) / .25); return t > t0 ? `<g transform="translate(${x},${y}) rotate(-9) scale(${1.6 - .6 * st})" opacity="${st}"><rect x="${-s0.length * size * .55 - 26}" y="-${size}" width="${s0.length * size * 1.1 + 52}" height="${size * 2}" rx="12" fill="rgba(20,18,24,.7)" stroke="${col}" stroke-width="8"/>${txt(0, size * .34, s0, { size, color: col, shadow: false, serif: true })}</g>` : ''; };
const cap = (y, s0, col = Y, size = 46) => `<g>${card(CX - s0.length * size * .55 - 40, y - size - 18, s0.length * size * 1.1 + 80, size * 1.9, { fill: 'rgba(18,16,24,.86)', stroke: col })}${txt(CX, y + 4, s0, { size, color: col, serif: true })}</g>`;
// ── 部品：精子・卵子 ──
const DEF = `<defs><radialGradient id="egg" cx=".45" cy=".42" r=".6"><stop offset="0" stop-color="#eaf6ff" stop-opacity=".95"/><stop offset=".55" stop-color="#9fd0f0" stop-opacity=".7"/><stop offset="1" stop-color="#4a8ac0" stop-opacity=".35"/></radialGradient><radialGradient id="eggOld" cx=".45" cy=".42" r=".6"><stop offset="0" stop-color="#e8e2d4" stop-opacity=".9"/><stop offset=".6" stop-color="#b0a890" stop-opacity=".6"/><stop offset="1" stop-color="#6a6250" stop-opacity=".3"/></radialGradient><radialGradient id="glw" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="#fff" stop-opacity=".9"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient><radialGradient id="halo" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="#ffb0d0" stop-opacity=".55"/><stop offset="1" stop-color="#ffb0d0" stop-opacity="0"/></radialGradient></defs>`;
const sp = (x, y, ang, s = 1, col = '#f4f8ff', t = 0, ph = 0, op = 1) => { let d = 'M0,0'; for (let i = 1; i <= 10; i++) d += ` L${-i * 7},${Math.sin(t * 14 + ph + i * .8) * (1.5 + i * .55)}`; return `<g transform="translate(${x.toFixed(1)},${y.toFixed(1)}) rotate(${ang}) scale(${s})" opacity="${op}"><path d="${d}" stroke="${col}" stroke-width="2.6" fill="none" stroke-linecap="round" opacity=".85"/><ellipse cx="6" cy="0" rx="9" ry="6" fill="${col}"/></g>`; };
const egg = (x, y, r, o = {}) => { const t = o.t || 0; let s = `<circle cx="${x}" cy="${y}" r="${r * 1.35}" fill="url(#halo)" opacity="${o.halo ?? .6}"/>`; const n = Math.round(r / 6);
  for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2 + t * .05, rr = r * (1.08 + .05 * Math.sin(i * 3.1)); s += `<circle cx="${x + Math.cos(a) * rr}" cy="${y + Math.sin(a) * rr}" r="${r * .07}" fill="${o.old ? '#b8ae98' : '#d8eefc'}" opacity=".55"/>`; }
  s += `<circle cx="${x}" cy="${y}" r="${r}" fill="url(#${o.old ? 'eggOld' : 'egg'})" stroke="${o.shell || (o.old ? '#d0c8b0' : '#e6f6ff')}" stroke-width="${o.sw || r * .06}"/><circle cx="${x - r * .15}" cy="${y - r * .1}" r="${r * .28}" fill="${o.old ? '#e8e0cc' : '#f4fbff'}" opacity=".55"/>`;
  if (o.eyes) { const bl = (Math.sin(t * 2.3) > .97) ? .1 : 1, lx = o.look || 0; s += `<ellipse cx="${x - r * .25}" cy="${y - r * .05}" rx="${r * .1}" ry="${r * .13 * bl * o.eyes}" fill="#1b2a3a"/><ellipse cx="${x + r * .25}" cy="${y - r * .05}" rx="${r * .1}" ry="${r * .13 * bl * o.eyes}" fill="#1b2a3a"/><circle cx="${x - r * .25 + lx * r * .04}" cy="${y - r * .08}" r="${r * .035}" fill="#fff"/><circle cx="${x + r * .25 + lx * r * .04}" cy="${y - r * .08}" r="${r * .035}" fill="#fff"/>`; }
  return s; };
const BG = (top = '#0c1424', bot = '#05070e') => `<rect width="1920" height="1080" fill="${top}"/><rect width="1920" height="1080" fill="url(#vig)"/><defs><radialGradient id="vig" cx=".5" cy=".45" r=".75"><stop offset="0" stop-color="${top}" stop-opacity="0"/><stop offset="1" stop-color="${bot}" stop-opacity=".95"/></radialGradient></defs>`;
// 群れ：n匹が (x0..x1) を流れる
const swarm = (t, n, seed, f) => { const r = rng(seed); let s = ''; for (let i = 0; i < n; i++) { const a = r(), b = r(), c = r(); s += f(i, a, b, c); } return s; };
const flow = (t, n, seed, o = {}) => swarm(t, n, seed, (i, a, b, c) => { const sp0 = (o.v || 160) * (.7 + .6 * b), x = ((a * 2200 + t * sp0) % 2200) - 140, y = (o.y0 || 300) + c * (o.h || 480) + Math.sin(t * 2 + i) * 10; const dead = o.dead && o.dead(i, x, a, b, c); return sp(x, y, Math.sin(t * 3 + i) * 8, o.s || 1, dead ? '#5a5a66' : (o.col || '#f4f8ff'), t, i, dead ? .45 : 1); });
// 面接室
const room = (t, inner = '') => `<rect x="0" y="0" width="1920" height="1080" fill="#1c1a22"/><rect x="0" y="720" width="1920" height="360" fill="#2a2630"/><rect x="200" y="120" width="1520" height="560" fill="#24212b" stroke="#3a3542" stroke-width="4"/><rect x="760" y="160" width="400" height="220" rx="10" fill="#2e3a4a" stroke="#4a5a70" stroke-width="4"/><path d="M960,160 v220 M760,270 h400" stroke="#4a5a70" stroke-width="4"/>` + inner + `<rect x="560" y="640" width="800" height="40" rx="8" fill="#6a4a36"/><rect x="600" y="680" width="40" height="200" fill="#4a3426"/><rect x="1280" y="680" width="40" height="200" fill="#4a3426"/>`;
const SC = [];

// ===== プロローグ =====
